CREATE DATABASE IF NOT EXISTS baruch_engineers CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
USE baruch_engineers;

CREATE TABLE IF NOT EXISTS admins (id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY,email VARCHAR(190) NOT NULL UNIQUE,password_hash VARBINARY(255) NOT NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS categories (id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY,name VARCHAR(120) NOT NULL UNIQUE,slug VARCHAR(140) NOT NULL UNIQUE,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS products (id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY,category_id INT UNSIGNED NOT NULL,sku VARCHAR(80) NOT NULL UNIQUE,name VARCHAR(255) NOT NULL,description TEXT,price DECIMAL(10,2) NULL,stock INT UNSIGNED NOT NULL DEFAULT 0,reserved_stock INT UNSIGNED NOT NULL DEFAULT 0,image_path VARCHAR(255),is_active TINYINT(1) NOT NULL DEFAULT 1,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,CONSTRAINT fk_products_category FOREIGN KEY(category_id) REFERENCES categories(id));
CREATE TABLE IF NOT EXISTS orders (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,order_number VARCHAR(30) NOT NULL UNIQUE,customer_name VARCHAR(160) NOT NULL,customer_email VARCHAR(190) NOT NULL,customer_phone VARCHAR(40) NOT NULL,delivery_address TEXT NOT NULL,delivery_city VARCHAR(80) NOT NULL,delivery_pin VARCHAR(12) NOT NULL,subtotal DECIMAL(10,2) NOT NULL,status ENUM('New order','Confirmed','Processing','Packed','Shipped','Delivered','Cancelled') NOT NULL DEFAULT 'New order',payment_status ENUM('Pending','Paid','Failed','Refunded') NOT NULL DEFAULT 'Pending',created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS order_items (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,order_id BIGINT UNSIGNED NOT NULL,product_id INT UNSIGNED NOT NULL,product_name VARCHAR(255) NOT NULL,unit_price DECIMAL(10,2) NULL,quantity INT UNSIGNED NOT NULL,CONSTRAINT fk_items_order FOREIGN KEY(order_id) REFERENCES orders(id) ON DELETE CASCADE,CONSTRAINT fk_items_product FOREIGN KEY(product_id) REFERENCES products(id));
CREATE INDEX idx_orders_status ON orders(status); CREATE INDEX idx_products_category ON products(category_id);
